const assets = $json.assets || [];

const trackedSymbols = ['BTC', 'ETH'];

const trackedAssets = assets.filter(asset =>
  trackedSymbols.includes(asset.symbol)
);

return [
  {
    json: {
      assets: trackedAssets,
      updatedAt: $json.updatedAt
    }
  }
];

const assets = $json.assets || [];

const requiredSymbols = ['BTC', 'ETH'];

// ========================================
// BASIC VALIDATION
// ========================================

const missingAssets = [];
const invalidAssets = [];

for (const symbol of requiredSymbols) {
  const asset = assets.find(a => a.symbol === symbol);

  if (!asset) {
    missingAssets.push(symbol);
    continue;
  }

  const flow = asset.netFlowUsdM;

  // IMPORTANT:
  // 0 is a VALID ETF flow value.
  if (
    flow === null ||
    flow === undefined ||
    flow === '' ||
    Number.isNaN(Number(flow))
  ) {
    invalidAssets.push(symbol);
  }
}


// ========================================
// GROUP ASSETS BY DATE
// ========================================

const assetsByDate = {};

for (const asset of assets) {
  if (!asset.date) continue;

  if (!assetsByDate[asset.date]) {
    assetsByDate[asset.date] = [];
  }

  assetsByDate[asset.date].push(asset.symbol);
}


// ========================================
// FIND LATEST DATE
// ========================================

const dates = Object.keys(assetsByDate).sort();

const latestDate =
  dates.length > 0
    ? dates[dates.length - 1]
    : null;


// ========================================
// CHECK WHICH ASSETS HAVE LATEST DATE
// ========================================

const assetsOnLatestDate = latestDate
  ? assets.filter(a => a.date === latestDate)
  : [];

const symbolsOnLatestDate =
  assetsOnLatestDate.map(a => a.symbol);

const waitingFor = requiredSymbols.filter(
  symbol => !symbolsOnLatestDate.includes(symbol)
);


// ========================================
// FINAL STATUS
// ========================================

const basicDataValid =
  missingAssets.length === 0 &&
  invalidAssets.length === 0;

const allAssetsSameDate =
  basicDataValid &&
  waitingFor.length === 0;

return [
  {
    json: {
      assets,
      updatedAt: $json.updatedAt,

      validation: {
        basicDataValid,
        allAssetsSameDate,
        latestDate,

        missingAssets,
        invalidAssets,
        waitingFor,

        assetsByDate
      }
    }
  }
];

const assets = $json.assets || [];
const validation = $json.validation || {};

const targetDate = validation.latestDate;

// ========================================
// NO TRADING DATE
// ========================================

if (!targetDate) {
  return [
    {
      json: {
        ...$json,
        publishCheck: {
          targetDate: null,
          readyAssets: [],
          pendingAssets: [],
          readyCount: 0,
          totalTracked: 2,
          shouldContinue: false,
          reason: 'NO_TARGET_DATE'
        }
      }
    }
  ];
}


// ========================================
// ASSETS ON TARGET DATE
// ========================================

const readyAssets = assets.filter(
  asset => asset.date === targetDate
);

const pendingAssets = assets
  .filter(asset => asset.date !== targetDate)
  .map(asset => ({
    symbol: asset.symbol,
    lastAvailableDate: asset.date
  }));


// ========================================
// FINAL DATA GUARD
// BTC + ETH must be on the same date.
// ========================================

const shouldContinue =
  validation.basicDataValid === true &&
  validation.allAssetsSameDate === true &&
  readyAssets.length === 2;


// ========================================
// OUTPUT
// ========================================

return [
  {
    json: {
      ...$json,

      publishCheck: {
        targetDate,
        readyAssets,
        pendingAssets,
        readyCount: readyAssets.length,
        totalTracked: 2,
        shouldContinue,

        reason: shouldContinue
          ? 'ALL_ASSETS_READY'
          : 'WAITING_FOR_ALL_ASSETS'
      }
    }
  }
];

// ==========================================
// CHECK NEW ETF TRADING DATE
// Duplicate protection
// ==========================================

const lastPublishedDate = $json.lastPublishedDate;

const targetDate =
  $('Build Final ETF Dataset').first().json.targetDate;

if (!targetDate) {
  throw new Error('Final ETF target trading date not found');
}

if (!lastPublishedDate) {
  throw new Error('Last published ETF date not found');
}

const isNewTradingDate =
  targetDate > lastPublishedDate;

return [
  {
    json: {
      targetDate,
      lastPublishedDate,
      isNewTradingDate,
      decision: isNewTradingDate
        ? 'CONTINUE'
        : 'STOP'
    }
  }
];

// ==========================================
// FYNBEAT — DAILY CRYPTO ETF TWEET V2
// BTC / ETH REQUIRED
// HISTORICAL CONTEXT PRESERVED
// NO TOTAL NET FLOW
// ==========================================

const targetDate = $json.targetDate;
const assets = $json.assets || [];
const historicalTweetContext =
  $json.historicalTweetContext || {};

const requiredSymbols = ['BTC', 'ETH'];
const displayOrder = ['BTC', 'ETH'];

const displayNames = {
  BTC: 'BTC',
  ETH: 'ETH'
};

// ------------------------------------------
// 1. DATE VALIDATION
// ------------------------------------------

if (
  typeof targetDate !== 'string' ||
  !/^\d{4}-\d{2}-\d{2}$/.test(targetDate) ||
  new Date(`${targetDate}T12:00:00Z`)
    .toISOString()
    .slice(0, 10) !== targetDate
) {
  throw new Error('Invalid ETF target date.');
}

// ------------------------------------------
// 2. DATA VALIDATION
// ------------------------------------------

if (!Array.isArray(assets)) {
  throw new Error('ETF assets must be an array.');
}

const seenSymbols = new Set();

for (const asset of assets) {

  if (!displayOrder.includes(asset.symbol)) {
    throw new Error(
      `Unexpected ETF symbol: ${asset.symbol}`
    );
  }

  if (seenSymbols.has(asset.symbol)) {
    throw new Error(
      `Duplicate ETF symbol: ${asset.symbol}`
    );
  }

  seenSymbols.add(asset.symbol);

  if (
    asset.date !== targetDate ||
    typeof asset.netFlowUsdM !== 'number' ||
    !Number.isFinite(asset.netFlowUsdM)
  ) {
    throw new Error(
      `Invalid ETF data for ${asset.symbol}`
    );
  }
}

// BTC and ETH must always exist.
for (const symbol of requiredSymbols) {
  if (!seenSymbols.has(symbol)) {
    throw new Error(
      `Required ETF data missing: ${symbol}`
    );
  }
}

// Sort available assets into fixed order.
const sortedAssets = [...assets].sort(
  (a, b) =>
    displayOrder.indexOf(a.symbol) -
    displayOrder.indexOf(b.symbol)
);

// ------------------------------------------
// 3. DATE FORMAT
// ------------------------------------------

const date = new Date(`${targetDate}T12:00:00Z`);

const formattedDate = date.toLocaleDateString(
  'en-US',
  {
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC'
  }
);

// ------------------------------------------
// 4. FLOW FORMAT
// ------------------------------------------

function formatFlow(value) {

  const flow = Number(value);

  if (flow > 0) {
    return `+$${flow.toFixed(1)}M 🟢`;
  }

  if (flow < 0) {
    return `-$${Math.abs(flow).toFixed(1)}M 🔴`;
  }

  return '$0.0M ⚪';
}

// ------------------------------------------
// 5. DAILY ETF LINES
// ------------------------------------------

const lines = sortedAssets.map(asset => {

  const name = displayNames[asset.symbol];

  return `${name}: ${formatFlow(asset.netFlowUsdM)}`;
});

// No Total Net Flow calculation.

const baseTweet =
`Crypto ETF Flows — ${formattedDate}

${lines.join('\n')}`;

// ------------------------------------------
// 6. HISTORICAL CONTEXT
// ------------------------------------------

const historicalLines = ['BTC', 'ETH']
  .map(symbol =>
    historicalTweetContext[symbol]?.historicalText
  )
  .filter(Boolean);

let tweetText = baseTweet;

if (historicalLines.length > 0) {

  tweetText += `

${historicalLines.join('\n')}`;
}

// ------------------------------------------
// 7. COMPACT HISTORICAL FALLBACK
// ------------------------------------------

if (tweetText.length > 280) {

  const compactHistoricalLines = [];

  for (const symbol of ['BTC', 'ETH']) {

    const text =
      historicalTweetContext[symbol]?.historicalText;

    if (!text) continue;

    const streakMatch = text.match(
      /(\d+) consecutive days of (inflows|outflows)/
    );

    const flowMatch = text.match(
      /5-day net flow (?:to|stands at) ([+-]?\$[\d.]+[BM]|\$0)/
    );

    const parts = [];

    if (streakMatch) {

      const days = streakMatch[1];

      const direction =
        streakMatch[2] === 'inflows'
          ? 'inflow'
          : 'outflow';

      parts.push(`${days}d ${direction} streak`);
    }

    if (flowMatch) {
      parts.push(`5D ${flowMatch[1]}`);
    }

    if (parts.length > 0) {

      compactHistoricalLines.push(
        `${symbol}: ${parts.join(' | ')}`
      );
    }
  }

  if (compactHistoricalLines.length > 0) {

    tweetText =
`${baseTweet}

${compactHistoricalLines.join('\n')}`;
  }
}

// ------------------------------------------
// 8. FINAL TWEET SAFETY
// ------------------------------------------

if (tweetText.length > 280) {
  throw new Error(
    `Tweet exceeds 280 characters (${tweetText.length}).`
  );
}

// ------------------------------------------
// 9. OUTPUT
// ------------------------------------------

return [{
  json: {
    targetDate,
    assets: sortedAssets,
    assetCount: sortedAssets.length,
    missingOptionalAssets:
      displayOrder
        .filter(symbol =>
          !requiredSymbols.includes(symbol) &&
          !seenSymbols.has(symbol)
        ),
    historicalTweetContext,
    tweetLength: tweetText.length,
    tweetText
  }
}];

// ==========================================
// FYNBEAT — BUILD SUMMARY ETF DATASET V2
// BTC + ETH REQUIRED
// NO TOTAL NET FLOW
// ==========================================

const tradingData =
  $('Build Final ETF Dataset').first().json;

const targetDate = tradingData.targetDate;
const assets = tradingData.assets;

const REQUIRED = ['BTC', 'ETH'];
const OPTIONAL = [];
const ALLOWED = [...REQUIRED, ...OPTIONAL];

// ==========================================
// DATASET VALIDATION
// ==========================================

if (
  typeof targetDate !== 'string' ||
  !/^\d{4}-\d{2}-\d{2}$/.test(targetDate)
) {
  throw new Error('Invalid ETF targetDate.');
}

if (!Array.isArray(assets)) {
  throw new Error('Final ETF assets array missing.');
}

const seen = new Set();

for (const asset of assets) {
  if (!ALLOWED.includes(asset.symbol)) {
    throw new Error(
      `Unexpected ETF symbol: ${asset.symbol}`
    );
  }

  if (seen.has(asset.symbol)) {
    throw new Error(
      `Duplicate ETF symbol: ${asset.symbol}`
    );
  }

  seen.add(asset.symbol);

  if (
    asset.date !== targetDate ||
    typeof asset.netFlowUsdM !== 'number' ||
    !Number.isFinite(asset.netFlowUsdM)
  ) {
    throw new Error(
      `Invalid ETF data for ${asset.symbol}`
    );
  }
}

// ==========================================
// REQUIRED ASSET CHECK
// ==========================================

const readySymbols = assets.map(a => a.symbol);

const missingRequiredSymbols = REQUIRED.filter(
  symbol => !readySymbols.includes(symbol)
);

const missingOptionalSymbols = OPTIONAL.filter(
  symbol => !readySymbols.includes(symbol)
);

if (missingRequiredSymbols.length > 0) {
  throw new Error(
    `Mandatory ETF assets missing: ${missingRequiredSymbols.join(', ')}`
  );
}

// ==========================================
// OUTPUT
// ==========================================

const allAssetsResolved =
  missingRequiredSymbols.length === 0;

const allAssetsReady =
  missingOptionalSymbols.length === 0;

return [{
  json: {
    targetDate,
    assets,
    assetCount: assets.length,

    // True when BTC and ETH are ready
    allAssetsResolved,

    missingAssets: [
      ...missingRequiredSymbols,
      ...missingOptionalSymbols
    ],

    finalDatasetSource:
      tradingData.finalDatasetSource,

    validation: {
      ...tradingData.validation,
      requiredAssetsReady: true,
      allAssetsReady,
      missingRequiredSymbols,
      missingOptionalSymbols
    }
  }
}];

const assets = $json.assets ?? [];

const tracked = assets.filter(asset =>
  ['BTC', 'ETH'].includes(asset.symbol)
);

return tracked.map(asset => ({
  json: {
    date: asset.date,
    symbol: asset.symbol,
    netFlow: asset.netFlowUsdM,
    direction:
      asset.netFlowUsdM > 0
        ? 'inflow'
        : asset.netFlowUsdM < 0
          ? 'outflow'
          : 'flat'
  }
}));

const rows = $input.all().map(item => item.json);

const symbols = ['BTC', 'ETH'];
const results = [];

for (const symbol of symbols) {
  // Bu asset'in kayıtlarını al ve en yeni trading day önce olacak şekilde sırala
  const history = rows
    .filter(row => row.symbol === symbol)
    .sort((a, b) => b.date.localeCompare(a.date));

  if (history.length === 0) {
    results.push({
      json: {
        symbol,
        historyDays: 0,
        streak: 0,
        streakDirection: null,
        showStreak: false,
        fiveDayNetFlow: null,
        show5DayFlow: false,
      }
    });
    continue;
  }

  // En güncel günün yönü
  const currentDirection = history[0].direction;

  // Consecutive streak
  let streak = 0;

  for (const row of history) {
    if (row.direction === currentDirection) {
      streak++;
    } else {
      break;
    }
  }

  // Son 5 trading day
  const lastFive = history.slice(0, 5);

  const hasFiveDays = lastFive.length === 5;

  const fiveDayNetFlow = hasFiveDays
    ? lastFive.reduce((sum, row) => sum + Number(row.netFlow), 0)
    : null;

  results.push({
    json: {
      symbol,
      latestDate: history[0].date,
      latestNetFlow: Number(history[0].netFlow),
      latestDirection: currentDirection,

      historyDays: history.length,

      streak,
      streakDirection: currentDirection,
      showStreak: streak >= 3,

      fiveDayNetFlow: hasFiveDays
        ? Number(fiveDayNetFlow.toFixed(1))
        : null,
      show5DayFlow: hasFiveDays,
    }
  });
}

return results;

const items = $input.all().map(item => item.json);

const context = {};

for (const item of items) {
  context[item.symbol] = {
    historyDays: item.historyDays,

    streak: {
      days: item.streak,
      direction: item.streakDirection,
      show: item.showStreak
    },

    fiveDay: {
      netFlowUsdM: item.fiveDayNetFlow,
      show: item.show5DayFlow
    }
  };
}

return [
  {
    json: {
      historicalContext: context
    }
  }
];

const historicalContext =
  $('Build Historical Context Object').first().json.historicalContext;

const dailyDataset =
  $('Preserve ETF Daily Dataset').first().json;

return [{
  json: {
    ...dailyDataset,
    historicalContext
  }
}];

const data = $input.first().json;
const context = data.historicalContext ?? {};

const results = {};

function formatFlow(valueM) {
  const abs = Math.abs(valueM);

  if (abs >= 1000) {
    return `$${(abs / 1000).toFixed(2)}B`;
  }

  return `$${abs.toFixed(1)}M`;
}

function signedFlow(valueM) {
  if (valueM > 0) {
    return `+${formatFlow(valueM)}`;
  }

  if (valueM < 0) {
    return `-${formatFlow(valueM)}`;
  }

  return '$0';
}

for (const symbol of ['BTC', 'ETH']) {
  const assetContext = context[symbol];

  if (!assetContext) {
    results[symbol] = {
      historicalText: null
    };
    continue;
  }

  const streak = assetContext.streak;
  const fiveDay = assetContext.fiveDay;

  // Only inflow/outflow streaks are valid.
  // "flat" (0 flow) must never create a streak message.
  const showStreak =
    streak?.show === true &&
    ['inflow', 'outflow'].includes(streak?.direction);

  const showFiveDay =
    fiveDay?.show === true &&
    fiveDay.netFlowUsdM !== null;

  let historicalText = null;

  // ========================================
  // STREAK + 5-DAY
  // ========================================

  if (showStreak && showFiveDay) {
    const directionText =
      streak.direction === 'inflow'
        ? 'inflows'
        : 'outflows';

    historicalText =
      `${symbol} has now recorded ${streak.days} consecutive days of ${directionText}, ` +
      `bringing its 5-day net flow to ${signedFlow(fiveDay.netFlowUsdM)}.`;
  }

  // ========================================
  // STREAK ONLY
  // ========================================

  else if (showStreak) {
    const directionText =
      streak.direction === 'inflow'
        ? 'inflows'
        : 'outflows';

    historicalText =
      `${symbol} has now recorded ${streak.days} consecutive days of ${directionText}.`;
  }

  // ========================================
  // 5-DAY ONLY
  // ========================================

  else if (showFiveDay) {
    historicalText =
      `${symbol}'s 5-day net flow stands at ${signedFlow(fiveDay.netFlowUsdM)}.`;
  }

  results[symbol] = {
    historicalText
  };
}

return [
  {
    json: {
      ...data,
      historicalTweetContext: results
    }
  }
];

const data = $json;

const targetDate =
  data.publishCheck?.targetDate;

const assets =
  data.assets || [];

// CryptoETF artık final dataset kaynağı değil.
// Buradaki görevi güvenilir bir ETF targetDate sağlamaktır.

const readyAssets = assets.filter(
  asset => asset.date === targetDate
);

const pendingAssets = assets
  .filter(asset => asset.date !== targetDate)
  .map(asset => ({
    symbol: asset.symbol,
    lastAvailableDate: asset.date
  }));

// Final BTC/ETH doğrulaması SoSoValue/Farside tarafında yapılır.
// Burada yalnızca geçerli bir targetDate olması yeterli.
const shouldContinue =
  typeof targetDate === 'string' &&
  /^\d{4}-\d{2}-\d{2}$/.test(targetDate);

return [
  {
    json: {
      ...data,

      assets,

      publishCheck: {
        ...data.publishCheck,

        targetDate,
        readyAssets,
        pendingAssets,

        readyCount: readyAssets.length,
        totalTracked: 2,

        shouldContinue,

        reason: shouldContinue
          ? 'TARGET_DATE_READY_FOR_SURF_FINAL_CHECK'
          : 'NO_VALID_TARGET_DATE'
      },

      finalDatasetSource: 'CRYPTOETF_TARGET_DATE'
    }
  }
];

// ==========================================
// BUILD WEEKLY BTC & ETH DATASET
// TEMP TEST MODE: 2026-08-31 → 2026-09-04
// Grafik testi tamamlanınca current-week moduna döneceğiz.
// ==========================================

// BTC ve ETH historical verilerini ilgili node'lardan al
const btc = $('Get BTC Daily Flow History').first().json;
const eth = $('Get ETH Daily Flow History').first().json;


// ------------------------------------------
// ISTANBUL DATE SETUP
// ------------------------------------------

const now = new Date();

const istanbulParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Istanbul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(now);

const year = Number(
  istanbulParts.find(p => p.type === 'year').value
);

const month = Number(
  istanbulParts.find(p => p.type === 'month').value
);

const day = Number(
  istanbulParts.find(p => p.type === 'day').value
);

// UTC kullanarak date hesaplamalarını stabil tutuyoruz
const today = new Date(
  Date.UTC(year, month - 1, day)
);


// ------------------------------------------
// NORMAL PRODUCTION WEEK CALCULATION
// Şimdilik hesaplanıyor fakat aşağıda test
// tarihleri kullanılıyor.
// ------------------------------------------

const dayOfWeek = today.getUTCDay(); // Sun=0 ... Sat=6

const daysSinceMonday = (dayOfWeek + 6) % 7;

const monday = new Date(today);

monday.setUTCDate(
  today.getUTCDate() - daysSinceMonday
);

const friday = new Date(monday);

friday.setUTCDate(
  monday.getUTCDate() + 4
);

const iso = (d) =>
  d.toISOString().slice(0, 10);


// ------------------------------------------
// TEMP TEST WEEK
// ------------------------------------------

// PRODUCTION: current week Monday -> Friday
const mondayStr = iso(monday);
const fridayStr = iso(friday);


// ------------------------------------------
// FILTER MONDAY → FRIDAY
// ------------------------------------------

const filterWeek = (days) =>
  days.filter(
    d =>
      d.date >= mondayStr &&
      d.date <= fridayStr
  );

const btcWeek = filterWeek(btc.days);
const ethWeek = filterWeek(eth.days);


// ------------------------------------------
// WEEKLY NET FLOW CALCULATION
// ------------------------------------------

const btcWeeklyNet = btcWeek.reduce(
  (sum, d) =>
    sum + Number(d.netFlowUsdM || 0),
  0
);

const ethWeeklyNet = ethWeek.reduce(
  (sum, d) =>
    sum + Number(d.netFlowUsdM || 0),
  0
);


// ------------------------------------------
// OUTPUT
// ------------------------------------------

return [
  {
    json: {

      week: {
        monday: mondayStr,
        friday: fridayStr,
      },

      btc: {
        symbol: 'BTC',
        days: btcWeek,
        weeklyNetUsdM:
          Math.round(btcWeeklyNet * 10) / 10,
      },

      eth: {
        symbol: 'ETH',
        days: ethWeek,
        weeklyNetUsdM:
          Math.round(ethWeeklyNet * 10) / 10,
      },

      validation: {

        btcDaysFound:
          btcWeek.length,

        ethDaysFound:
          ethWeek.length,

        fridayBTCReady:
          btcWeek.some(
            d => d.date === fridayStr
          ),

        fridayETHReady:
          ethWeek.some(
            d => d.date === fridayStr
          ),
      },
    },
  },
];

// ==========================================
// PREPARE WEEKLY ETF GRAPHIC
// FynBeat Weekly BTC & ETH ETF Report
// ==========================================

// Weekly dataset'i doğrudan ana dataset node'undan al.
// Böylece aradaki IF / Data Table node'larının output'una
// bağımlı kalmayız.
const data =
  $('Build Weekly BTC & ETH Dataset').first().json;

// ------------------------------------------
// HELPERS
// ------------------------------------------

const formatFlow = (value) => {
  const n = Number(value);

  const sign = n > 0 ? '+' : n < 0 ? '-' : '';
  const abs = Math.abs(n);

  if (abs >= 1000) {
    return `${sign}$${(abs / 1000).toFixed(2)}B`;
  }

  return `${sign}$${abs.toFixed(1)}M`;
};

const formatDate = (dateString) => {
  const date = new Date(`${dateString}T00:00:00Z`);

  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  }).format(date);
};

const iso = (date) =>
  date.toISOString().slice(0, 10);

// ------------------------------------------
// EXPECTED MONDAY → FRIDAY DATES
// ------------------------------------------

const monday =
  new Date(`${data.week.monday}T00:00:00Z`);

const expectedDays = [
  'MON',
  'TUE',
  'WED',
  'THU',
  'FRI',
].map((day, index) => {

  const date = new Date(monday);

  date.setUTCDate(
    monday.getUTCDate() + index
  );

  return {
    day,
    date: iso(date),
  };
});

// ------------------------------------------
// BUILD DAILY DATA SAFELY
// ------------------------------------------

const chartData = expectedDays.map(expected => {

  const btc = data.btc.days.find(
    item => item.date === expected.date
  );

  const eth = data.eth.days.find(
    item => item.date === expected.date
  );

  // Eksik gün varsa grafik oluşturma.
  // Missing data hiçbir zaman 0 kabul edilmez.
  if (!btc || !eth) {
    throw new Error(
      `Weekly ETF data incomplete for ${expected.date}`
    );
  }

  // Gerçek 0 geçerlidir.
  // Sadece null / undefined eksik veri sayılır.
  if (
    btc.netFlowUsdM === null ||
    btc.netFlowUsdM === undefined ||
    eth.netFlowUsdM === null ||
    eth.netFlowUsdM === undefined
  ) {
    throw new Error(
      `Weekly ETF flow missing for ${expected.date}`
    );
  }

  return {
    day: expected.day,
    date: expected.date,

    btc: Number(btc.netFlowUsdM),
    eth: Number(eth.netFlowUsdM),

