const rows = data.chartData;

// ------------------------------------------------------------
// SETTINGS
// ------------------------------------------------------------

const WIDTH = 1200;
const HEIGHT = 675;

const chartHeight = 285;
const zeroY = 190;

const maxPositiveHeight = 145;
const maxNegativeHeight = 62;

// Fixed professional chart scale.
// The visual axis automatically adapts to the largest value.

const allValues = rows.flatMap(r => [
  Number(r.btc),
  Number(r.eth)
]);

const maxAbs = Math.max(
  ...allValues.map(v => Math.abs(v)),
  1
);

// Nice Y-axis ceiling

function niceCeiling(value) {

  if (value <= 200) return 200;
  if (value <= 400) return 400;
  if (value <= 600) return 600;
  if (value <= 800) return 800;
  if (value <= 1000) return 1000;

  return Math.ceil(value / 500) * 500;
}

const axisMax = niceCeiling(maxAbs);

// ------------------------------------------------------------
// FORMATTING
// ------------------------------------------------------------

function money(value) {

  const n = Number(value);

  const sign = n >= 0 ? "+" : "-";
  const abs = Math.abs(n);

  if (abs >= 1000) {
    return `${sign}$${(abs / 1000).toFixed(2)}B`;
  }

  return `${sign}$${abs.toFixed(1)}M`;
}

function axisLabel(value) {

  if (value === 0) return "$0";

  if (Math.abs(value) >= 1000) {
    return `$${(Math.abs(value) / 1000).toFixed(1)}B`;
  }

  return `$${Math.abs(value)}M`;
}

// ------------------------------------------------------------
// BAR CALCULATIONS
// ------------------------------------------------------------

function positiveHeight(value) {

  return Math.max(
    4,
    (Math.abs(value) / axisMax) * maxPositiveHeight
  );
}

function negativeHeight(value) {

  return Math.max(
    4,
    (Math.abs(value) / axisMax) * maxPositiveHeight
  );
}

function buildBar(value, type) {

  const n = Number(value);
  const positive = n >= 0;

  const height = positive
    ? positiveHeight(n)
    : negativeHeight(n);

  const top = positive
    ? zeroY - height
    : zeroY;

  const labelTop = positive
    ? Math.max(3, top - 25)
    : Math.min(
        chartHeight - 26,
        zeroY + height + 7
      );

  return `
    <div
      class="flow-bar ${type}-bar"
      style="
        top:${top}px;
        height:${height}px;
      "
    ></div>

    <div
      class="bar-value ${type}-text"
      style="
        top:${labelTop}px;
      "
    >
      ${money(n)}
    </div>
  `;
}

// ------------------------------------------------------------
// DAY GROUPS
// ------------------------------------------------------------

const dayGroups = rows.map((r, index) => {

  return `
    <div class="day-group">

      <div class="bar-column btc-column">
        ${buildBar(r.btc, "btc")}
      </div>

      <div class="bar-column eth-column">
        ${buildBar(r.eth, "eth")}
      </div>

      <div class="day-label">
        ${r.day}
      </div>

    </div>
  `;

}).join("");

// ------------------------------------------------------------
// GRID
// ------------------------------------------------------------

const gridValues = [
  axisMax,
  axisMax * 0.75,
  axisMax * 0.50,
  axisMax * 0.25,
  0
];

const gridLines = gridValues.map((value, index) => {

  const y =
    zeroY -
    ((value / axisMax) * maxPositiveHeight);

  return `
    <div
      class="grid-line ${value === 0 ? "zero-grid" : ""}"
      style="top:${y}px"
    >
      <span class="axis-label">
        ${axisLabel(value)}
      </span>
    </div>
  `;

}).join("");

// Negative guide lines

const negativeGrid = [
  axisMax * 0.25,
  axisMax * 0.50
].map(value => {

  const y =
    zeroY +
    ((value / axisMax) * maxPositiveHeight);

  if (y >= chartHeight - 20) return "";

  return `
    <div
      class="grid-line negative-grid"
      style="top:${y}px"
    >
      <span class="axis-label">
        -${axisLabel(value)}
      </span>
    </div>
  `;

}).join("");

