// ==========================================
// BUILD SOSOVALUE ETF DATASET
// BTC + ETH ONLY
// ==========================================

const responses = $input.all();

const targetDate = $('Prepare Final ETF Dataset')
  .first().json.publishCheck?.targetDate;

if (!targetDate) {
  throw new Error('ETF targetDate not found.');
}

const assetMap = [
  { symbol: 'BTC', asset: 'bitcoin' },
  { symbol: 'ETH', asset: 'ethereum' }
];

const requiredSymbols = assetMap.map(a => a.symbol);

if (responses.length !== assetMap.length) {
  throw new Error(
    `Expected ${assetMap.length} SoSoValue responses, received ${responses.length}`
  );
}

const assets = [];
const missingAssets = [];

responses.forEach((item, index) => {
  const config = assetMap[index];
  const response = item.json;

  if (response.code !== 0) {
    throw new Error(`SoSoValue request failed for ${config.symbol}`);
  }

  if (!Array.isArray(response.data)) {
    throw new Error(`Invalid SoSoValue data for ${config.symbol}`);
  }

  const record = response.data.find(row => row.date === targetDate);

  if (!record) {
    missingAssets.push({ symbol: config.symbol, asset: config.asset, reason: 'TARGET_DATE_NOT_FOUND' });
    return;
  }

  if (
    record.total_net_inflow === null ||
    record.total_net_inflow === undefined ||
    record.total_net_inflow === ''
  ) {
    missingAssets.push({ symbol: config.symbol, asset: config.asset, reason: 'FLOW_NOT_READY' });
    return;
  }

  // 0 is a VALID flow value.
  const netFlowUsdM = Number(record.total_net_inflow) / 1_000_000;

  if (!Number.isFinite(netFlowUsdM)) {
    throw new Error(`Invalid ${config.symbol} flow for ${targetDate}`);
  }

  assets.push({
    symbol: config.symbol,
    asset: config.asset,
    date: targetDate,
    netFlowUsdM,
    source: 'SoSoValue'
  });
});

const readySymbols = assets.map(a => a.symbol);

const missingRequiredSymbols = requiredSymbols.filter(
  symbol => !readySymbols.includes(symbol)
);

const allAssetsReady = missingRequiredSymbols.length === 0;

return [{
  json: {
    targetDate,
    assets,
    missingAssets,
    validation: {
      readyCount: assets.length,
      totalRequired: requiredSymbols.length,
      allAssetsReady,
      requiredAssetsReady: allAssetsReady,
      readySymbols,
      missingSymbols: missingRequiredSymbols,
      missingRequiredSymbols,
      needsFallback: !allAssetsReady
    },
    datasetSource: 'SOSOVALUE'
  }
}];

// ==========================================
// FYNBEAT — BUILD FINAL ETF DATASET V3
// BTC + ETH ONLY
// ==========================================

const core = $input.first()?.json;

if (
  !core ||
  !Array.isArray(core.assets) ||
  typeof core.targetDate !== 'string'
) {
  // Core data not ready – stop quietly, next poll retries.
  return [];
}

const REQUIRED = ['BTC', 'ETH'];
const targetDate = core.targetDate;

if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
  throw new Error(`Invalid targetDate: ${targetDate}`);
}

const assets = [];
const invalidAssets = [];
const seen = new Set();

for (const asset of core.assets) {
  const symbol = asset.symbol;

  if (!REQUIRED.includes(symbol)) {
    // Ignore anything that is not BTC / ETH.
    continue;
  }

  if (seen.has(symbol)) {
    throw new Error(`Duplicate ETF symbol: ${symbol}`);
  }
  seen.add(symbol);

  const valid =
    asset.date === targetDate &&
    typeof asset.netFlowUsdM === 'number' &&
    Number.isFinite(asset.netFlowUsdM);

  if (!valid) {
    invalidAssets.push({ symbol, reason: 'INVALID_DATE_OR_FLOW' });
    continue;
  }

  assets.push({
    symbol,
    asset: asset.asset,
    date: targetDate,
    netFlowUsdM: asset.netFlowUsdM,
    source: asset.source
  });
}

const readySymbols = assets.map(a => a.symbol);

const missingRequiredSymbols = REQUIRED.filter(
  symbol => !readySymbols.includes(symbol)
);

if (missingRequiredSymbols.length > 0) {
  throw new Error(
    `Mandatory ETF data missing: ${missingRequiredSymbols.join(', ')}`
  );
}

assets.sort((a, b) => REQUIRED.indexOf(a.symbol) - REQUIRED.indexOf(b.symbol));

const fallbackUsed = core.validation?.fallbackUsed === true;

return [{
  json: {
    targetDate,
    assets,
    validation: {
      readyCount: assets.length,
      totalRequired: REQUIRED.length,
      requiredAssetsReady: true,
      allAssetsReady: true,
      readySymbols,
      missingSymbols: [],
      missingRequiredSymbols: [],
      invalidAssets,
      coreSource: core.datasetSource,
      fallbackUsed
    },
    finalDatasetSource: fallbackUsed
      ? 'SOSOVALUE_PLUS_FARSIDE_FALLBACK'
      : 'SOSOVALUE'
  }
}];

// ==========================================
// CHECK ETF DATE BEFORE FINAL DATA FETCH
// Early duplicate protection
// ==========================================

const lastPublishedDate = $json.lastPublishedDate;

const targetDate =
  $('Prepare Final ETF Dataset').first().json.publishCheck?.targetDate;

if (!targetDate) {
  throw new Error('ETF targetDate not found before final data fetch.');
}

if (!lastPublishedDate) {
  throw new Error('Last published ETF date not found.');
}

const shouldFetchFinalData =
  targetDate > lastPublishedDate;

return [{
  json: {
    targetDate,
    lastPublishedDate,
    shouldFetchFinalData,
    decision: shouldFetchFinalData
      ? 'FETCH_FINAL_DATA'
      : 'ALREADY_PUBLISHED'
  }
}];

// ==========================================
// PREPARE FARSIDE FALLBACK REQUESTS
// PRODUCTION MODE
//
// Only requests fallback for assets that
// SoSoValue could not resolve.
// ==========================================

const data = $input.first().json;

const targetDate = data.targetDate;

const missingSymbols =
  data.validation?.missingSymbols || [];

if (!targetDate) {
  throw new Error('ETF targetDate not found.');
}

if (missingSymbols.length === 0) {
  throw new Error(
    'Fallback requested but no missing symbols found.'
  );
}

const farsideConfig = {
  BTC: {
    asset: 'bitcoin',
    url: 'https://farside.co.uk/btc/'
  },

  ETH: {
    asset: 'ethereum',
    url: 'https://farside.co.uk/eth/'
  }
};

const requests = [];

for (const symbol of missingSymbols) {

  const config = farsideConfig[symbol];

  // No approved fallback source for this asset.
  // Do NOT invent a replacement.
  if (!config) {
    continue;
  }

  requests.push({
    json: {
      symbol,
      asset: config.asset,
      targetDate,
      url: config.url,
      source: 'Farside'
    }
  });
}

return requests;

// ==========================================
// ATTACH FARSIDE FALLBACK METADATA
// PRODUCTION MODE
//
// HTTP Request returns the HTML response,
// so request metadata is re-attached here.
// ==========================================

const responses = $input.all();

const requests =
  $('Prepare Farside Fallback Requests').all();

if (responses.length !== requests.length) {
  throw new Error(
    `Farside response/request count mismatch: ` +
    `${responses.length}/${requests.length}`
  );
}

return responses.map((response, index) => {

  const request =
    requests[index].json;

  const html =
    response.json.data;

  if (
    !html ||
    typeof html !== 'string'
  ) {
    throw new Error(
      `Farside HTML missing for ${request.symbol}`
    );
  }

  return {
    json: {
      symbol: request.symbol,
      asset: request.asset,
      targetDate: request.targetDate,
      url: request.url,
      source: 'Farside',
      html
    }
  };
});

// ==========================================
// PARSE FARSIDE FALLBACK DATA
// PRODUCTION MODE — BTC + ETH
//
// SAFETY:
// - Exact targetDate required
// - HTML page identity must match symbol
// - "-" / "—" / empty fund cell = NOT READY
// - 0.0 is valid
// - Negative "(5.0)" supported
// - Partial Total is NEVER accepted
// ==========================================

const items = $input.all();

const months = [
  'Jan', 'Feb', 'Mar', 'Apr',
  'May', 'Jun', 'Jul', 'Aug',
  'Sep', 'Oct', 'Nov', 'Dec'
];

const pageIdentity = {
  BTC: 'Bitcoin ETF Flow',
  ETH: 'Ethereum ETF Flow'
};

function parseNumber(value) {
  const cleaned = String(value)
    .replace(/,/g, '')
    .replace(/\$/g, '')
    .trim();

  if (
    !cleaned ||
    cleaned === '-' ||
    cleaned === '—'
  ) {
    throw new Error(
      `Missing Farside numeric value: ${value}`
    );
  }

  const isNegative =
    cleaned.startsWith('(') &&
    cleaned.endsWith(')');

  const numericText = isNegative
    ? cleaned.slice(1, -1).trim()
    : cleaned;

  const number = Number(numericText);

  if (!Number.isFinite(number)) {
    throw new Error(
      `Invalid Farside number: ${value}`
    );
  }

  return isNegative
    ? -Math.abs(number)
    : number;
}

return items.map(item => {

  const {
    symbol,
    asset,
    targetDate,
    html
  } = item.json;

  // ----------------------------------------
  // BASIC VALIDATION
  // ----------------------------------------

  if (!['BTC', 'ETH'].includes(symbol)) {
    throw new Error(
      `Unsupported Farside fallback symbol: ${symbol}`
    );
  }

  if (
    !targetDate ||
    !/^\d{4}-\d{2}-\d{2}$/.test(targetDate)
  ) {
    throw new Error(
      `Invalid targetDate for ${symbol}: ${targetDate}`
    );
  }

  if (
    !html ||
    typeof html !== 'string'
  ) {
    throw new Error(
      `Farside HTML missing for ${symbol}`
    );
  }

  // ----------------------------------------
  // PAGE IDENTITY CHECK
  // Prevent BTC/ETH response mix-up
  // ----------------------------------------

  const expectedPage =
    pageIdentity[symbol];

  if (!html.includes(expectedPage)) {
    throw new Error(
      `Farside page mismatch for ${symbol}. ` +
      `Expected page containing "${expectedPage}".`
    );
  }

  // ----------------------------------------
  // TARGET DATE
  // 2026-10-02 → "2 Oct 2026"
  // ----------------------------------------

  const [year, month, day] =
    targetDate.split('-').map(Number);

  const farsideDate =
    `${day} ${months[month - 1]} ${year}`;

  const dateIndex =
    html.indexOf(farsideDate);

  // Farside has not published this date yet.
  if (dateIndex === -1) {
    return {
      json: {
        symbol,
        asset,
        date: targetDate,
        ready: false,
        reason: 'TARGET_DATE_NOT_FOUND',
        source: 'Farside'
      }
    };
  }

  // ----------------------------------------
  // ISOLATE TARGET ROW
  // ----------------------------------------

  const rowStart =
    html.lastIndexOf('<tr', dateIndex);

  const rowEnd =
    html.indexOf('</tr>', dateIndex);

  if (
    rowStart === -1 ||
    rowEnd === -1
  ) {
    throw new Error(
      `Could not isolate ${symbol} row for ${farsideDate}`
    );
  }

  const row =
    html.slice(rowStart, rowEnd + 5);

  const cells = [
    ...row.matchAll(
      /<td\b[^>]*>([\s\S]*?)<\/td>/gi
    )
  ].map(match =>
    match[1]
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .trim()
  );

  // date + at least 1 fund + total
  if (cells.length < 3) {
    throw new Error(
      `Unexpected ${symbol} Farside row structure. ` +
      `Received ${cells.length} cells.`
    );
  }

  const fundValues =
    cells.slice(1, -1);

  const totalRaw =
    cells[cells.length - 1];

  // ----------------------------------------
  // COMPLETENESS CHECK
  // ----------------------------------------

  const missingFundIndexes = [];

  fundValues.forEach((value, index) => {
    if (
      value === '' ||
      value === '-' ||
      value === '—'
    ) {
      missingFundIndexes.push(index);
    }
  });

  // CRITICAL:
  // Farside may calculate a partial Total even
  // while individual fund values are missing.
  if (missingFundIndexes.length > 0) {
    return {
      json: {
        symbol,
        asset,
        date: targetDate,
        ready: false,
        reason: 'INCOMPLETE_FUND_DATA',
        missingFundIndexes,
        totalRaw,
        rawValues: cells,
        source: 'Farside'
      }
    };
  }

  // ----------------------------------------
  // FINAL FLOW
  // ----------------------------------------

  const netFlowUsdM =
    parseNumber(totalRaw);

  return {
    json: {
      symbol,
      asset,
      date: targetDate,
      netFlowUsdM,
      ready: true,
      reason: 'COMPLETE_FUND_DATA',
      source: 'Farside',

      validation: {
        fundCount: fundValues.length,
        missingFundCount: 0,
        totalRaw,
        rawValues: cells
      }
    }
  };
});

// ==========================================
// EVALUATE FARSIDE FALLBACK RESULT
// PRODUCTION MODE
//
// Every asset missing from SoSoValue must
// be successfully resolved by Farside.
//
// One unresolved asset = fallback NOT ready.
// ==========================================

const fallbackResults =
  $input.all().map(item => item.json);

const soso =
  $('Build SoSoValue ETF Dataset').first().json;

const targetDate =
  soso.targetDate;

const missingSymbols =
  soso.validation?.missingRequiredSymbols || [];

if (!targetDate) {
  throw new Error(
    'SoSoValue targetDate not found.'
  );
}

if (missingSymbols.length === 0) {
  throw new Error(
    'Fallback evaluation reached with no missing SoSoValue assets.'
  );
}

const resolvedAssets = [];
const unresolvedAssets = [];

for (const symbol of missingSymbols) {

  const result =
    fallbackResults.find(
      item => item.symbol === symbol
    );

  // No fallback result at all
  if (!result) {
    unresolvedAssets.push({
      symbol,
      reason: 'FALLBACK_RESULT_NOT_FOUND'
    });

    continue;
  }

  // Exact trading date required
  if (result.date !== targetDate) {
    unresolvedAssets.push({
      symbol,
      reason: 'FALLBACK_DATE_MISMATCH'
    });

    continue;
  }

  // Farside must explicitly declare READY
  if (result.ready !== true) {
    unresolvedAssets.push({
      symbol,
      reason:
        result.reason || 'FALLBACK_NOT_READY'
    });

    continue;
  }

  // Flow must actually exist.
  // Zero is VALID.
  if (
    result.netFlowUsdM === null ||
    result.netFlowUsdM === undefined ||
    !Number.isFinite(Number(result.netFlowUsdM))
  ) {
    unresolvedAssets.push({
      symbol,
      reason: 'INVALID_FALLBACK_FLOW'
    });

    continue;
  }

  resolvedAssets.push({
    symbol: result.symbol,
    asset: result.asset,
    date: result.date,
    netFlowUsdM:
      Number(result.netFlowUsdM),
    source: result.source
  });
}

const fallbackResolved =
  resolvedAssets.length === missingSymbols.length &&
  unresolvedAssets.length === 0;

return [{
  json: {
    targetDate,

    requiredFallbackSymbols:
      missingSymbols,

    resolvedAssets,
    unresolvedAssets,

    validation: {
      requiredCount:
        missingSymbols.length,

      resolvedCount:
        resolvedAssets.length,

      unresolvedCount:
        unresolvedAssets.length,

      fallbackResolved
    },

    datasetSource:
      'FARSIDE_FALLBACK'
  }
}];

// ==========================================
// BUILD RESOLVED CORE ETF DATASET
// BTC + ETH ONLY
//
// PATH A: SoSoValue has BTC + ETH → use SoSoValue.
// PATH B: SoSoValue incomplete → combine
//         SoSoValue assets + resolved Farside assets.
// ==========================================

const input = $input.first().json;
const soso = $('Build SoSoValue ETF Dataset').first().json;

const targetDate = soso.targetDate;

if (!targetDate) {
  throw new Error('SoSoValue targetDate not found.');
}

const requiredSymbols = ['BTC', 'ETH'];

const sosoAssets = Array.isArray(soso.assets) ? soso.assets : [];

const fallbackWasNeeded = soso.validation?.needsFallback === true;

let fallbackAssets = [];

if (fallbackWasNeeded) {
  // Arrived from Evaluate Farside Fallback Result.
  // Take whatever Farside resolved; the final check
  // below decides whether BTC + ETH are both present.
  fallbackAssets = Array.isArray(input.resolvedAssets)
    ? input.resolvedAssets
    : [];
}

const combinedAssets = [...sosoAssets, ...fallbackAssets];

const finalAssets = [];

for (const symbol of requiredSymbols) {
  const matches = combinedAssets.filter(a => a.symbol === symbol);

  // Exactly one source must resolve each asset.
  if (matches.length !== 1) continue;

  const asset = matches[0];

  if (
    asset.date !== targetDate ||
    asset.netFlowUsdM === null ||
    asset.netFlowUsdM === undefined ||
    !Number.isFinite(Number(asset.netFlowUsdM))
  ) {
    continue;
  }

  finalAssets.push({
    symbol: asset.symbol,
    asset: asset.asset,
    date: asset.date,
    netFlowUsdM: Number(asset.netFlowUsdM),
    source: asset.source
  });
}

const readySymbols = finalAssets.map(a => a.symbol);

const missingSymbols = requiredSymbols.filter(
  symbol => !readySymbols.includes(symbol)
);

const allAssetsReady = missingSymbols.length === 0;

return [{
  json: {
    targetDate,
    assets: finalAssets,
    validation: {
      readyCount: finalAssets.length,
      totalRequired: requiredSymbols.length,
      allAssetsReady,
      readySymbols,
      missingSymbols,
      fallbackUsed: fallbackWasNeeded,
      fallbackResolved: fallbackWasNeeded
        ? input.validation?.fallbackResolved === true
        : true
    },
    datasetSource: fallbackWasNeeded
      ? 'SOSOVALUE_PLUS_FARSIDE'
      : 'SOSOVALUE'
  }
}];
